const __nativeFetch=window.fetch.bind(window);window.fetch=async(input,init={})=>{const u=typeof input==='string'?input:(input?.url||'');if(u==='/api/catalog')return new Response(JSON.stringify({products:window.__MAXINES_PRODUCTS__||[],source:{mode:'embedded-v4-production-shell',claimedItems:41,visibleSkuRecords:13,checkoutEnabled:false,sourceArchiveSha256:'ca4681ccc7e3089a6bbaa0517dc01ecde4b78553a229df62b590010ef757ecd8'}}),{status:200,headers:{'content-type':'application/json'}});if(u==='/api/session')return new Response(JSON.stringify({authenticated:false,telegram:false,productionShell:true}),{status:200,headers:{'content-type':'application/json'}});if(u==='/api/checkout')return new Response(JSON.stringify({error:'Production checkout is intentionally disabled until the verified Telegram/Supabase payment backend is connected.'}),{status:503,headers:{'content-type':'application/json'}});if(u.startsWith('/api/order'))return new Response(JSON.stringify({error:'Order backend not activated in production shell.'}),{status:503,headers:{'content-type':'application/json'}});return __nativeFetch(input,init)};
